<?php
$secret = $_GET['secret'] ?? '';
if ($secret !== 'emuci2026import') die('Accès refusé');

require_once __DIR__ . '/includes/db.php';
$db = get_db();

$sql = base64_decode('');

// Séparer les commandes par ; en fin de ligne
$commands = preg_split('/;\s*\n/', $sql);
$success = 0;
$errors = [];

foreach ($commands as $cmd) {
    $cmd = trim($cmd);
    if (empty($cmd) || strpos($cmd, '--') === 0) continue;
    try {
        $db->exec($cmd);
        $success++;
    } catch (PDOException $e) {
        $msg = $e->getMessage();
        if (strpos($msg, 'already exists') === false) {
            $errors[] = substr($msg, 0, 150);
        }
    }
}

echo "<h2>Import terminé</h2>";
echo "<p>✅ $success commandes</p>";
if ($errors) {
    echo "<p>⚠️ " . count($errors) . " erreurs réelles:</p><ul>";
    foreach (array_slice($errors, 0, 10) as $e) echo "<li>" . htmlspecialchars($e) . "</li>";
    echo "</ul>";
}
echo "<p><b>SUPPRIMEZ import.php maintenant!</b></p>";
?>